from abc import ABC, abstractmethod
import logging
import os
import paramiko
from typing import Optional, List

from taf.rfrl.scrambling_logs_collector.resources.python.utils import admin_connection, vdu_admin_conn, vcu_admin_conn
from taf.rfrl.scrambling_logs_collector.resources.python.globals import LMP_IPV4, LMP_vCU_vDU_IP, OCP_CONNECTION_DETAILS
from taf.rfrl.scrambling_logs_collector.resources.python.utils import sftp_connection_available

logger = logging.getLogger(__name__)


class CollectedLogsNotFoundException(Exception):
    pass


class OCPConnectionNotAvailableException(Exception):
    pass


class ILogsCollector(ABC):
    """Interface for logs collector classes"""

    @abstractmethod
    def collect_logs_on_vm(self) -> List[str]:
        pass


class LogsCollector(ILogsCollector):
    """General class for gathering logs from BTS environment"""

    def __init__(self, log_type: str):
        self.input_type = log_type

    def get_collector(self):
        collectors = {
            '__snapshot__': OAMAdminSnapshotCollector,
            '__snapshot_vDU__': OAMAdminSnapshotCollectorCloudvDU,
            '__snapshot_vCU__': OAMAdminSnapshotCollectorCloudvCU,
            '__screl_classical__': ScrelSnapshotCollectorClassical,
            '__screl_vDU__': ScrelSnapshotCollectorCloudvDU,
            '__screl_vCU__': ScrelSnapshotCollectorCloudvCU,
            '__ru_snapshot__': RUSnapshotCollector,
            '__nop__': NOPLogsCollector,
        }
        return collectors.get(self.input_type, OAMAdminSnapshotCollector)

    def collect_logs_on_vm(self,
                           target_path: Optional[str] = None,
                           remote_host: Optional[str] = None) -> List[str]:
        """Main method for logs collection."""
        collector = self.get_collector()
        obj = collector(target_path) if target_path else collector()
        collected_logs = obj.collect_logs_on_vm(remote_host=remote_host) if remote_host else obj.collect_logs_on_vm()
        return collected_logs


class OAMAdminSnapshotCollector(ILogsCollector):
    """Class for gathering logs within OAM admin. It's intended to use this class
    for gathering the snapshots from BTS"""

    def __init__(self, target_path: Optional[str] = "snapshot_for_log_scrambling_SR.zip"):
        self.target_path = target_path

    def collect_logs_on_vm(self, timeout: int = 1200, remote_host: str = LMP_IPV4) -> List[str]:
        """
        Collect BTS classical snapshot with OAM admin
        :return     List with file path to the snapshot
        """
        with admin_connection(bts_host=remote_host) as conn:
            conn.get_snapshot(target_file_name=self.target_path, timeout=timeout)
        if self.target_path is None or not os.path.exists(self.target_path):
            raise CollectedLogsNotFoundException(f"Logs not found in {self.target_path} after collection!")
        return [self.target_path, ]


class OAMAdminSnapshotCollectorCloudvDU(ILogsCollector):
    """Class for gathering logs within OAM vDU. It's intended to use this class
    for gathering the snapshots from BTS"""

    def __init__(self, target_path=os.path.expanduser(os.path.join('~', 'snapshot_for_log_scrambling_CR_vDU'))):
        if not os.path.exists(target_path):
            os.makedirs(target_path)
        self.target_path = target_path

    def collect_logs_on_vm(self, timeout: int = 1200, remote_host: str = LMP_vCU_vDU_IP) -> List[str]:
        """
        Collect BTS cloud snapshot with OAM vDU
        :return     List with file path to the snapshot
        """
        with vdu_admin_conn(host=remote_host) as conn:
            conn.get_local_snapshot(directory=self.target_path, compressed_or_not=True, operation_timeout=timeout)
        contents = os.listdir(self.target_path)
        logger.info(f"vDU snapshot zip:{contents}")
        file_path = os.path.join(self.target_path, contents[0])
        if not os.path.exists(file_path):
            raise CollectedLogsNotFoundException(f"Logs not found in {self.target_path} after collection!")
        return [file_path, ]


