class ScrelSnapshotCollectorClassical(ILogsCollector):
    """
    Log collector for CB010699-SR-D - System Critical Event Logs
    """
    def __init__(self, target_path: Optional[str] = "SCREL_snapshot_for_log_scrambling_SR.zip"):
        self.target_path = target_path

    def collect_logs_on_vm(self, timeout: int = 600, remote_host: str = LMP_IPV4) -> List[str]:
        """
        Collect SCREL with OAM admin
        :return     List with file path to the SCREL
        """
        with admin_connection(bts_host=remote_host) as conn:
            conn.collect_local_screl(target_file_name=self.target_path, timeout=timeout, include_pmfm_data=True)
        if self.target_path is None or not os.path.exists(self.target_path):
            raise CollectedLogsNotFoundException(f"Logs not found in {self.target_path} after collection!")
        return [self.target_path, ]


